# Таблица значений функции
for x in (-2, -1, 0, 1, 2):
    print(x, x ** 2)

# Функция как математическая модель
def model(x):
    return 2 * x + 3

for x in (0, 1, 4):
    print(x, model(x))

params = 13_000_000_000
for bits in [16, 8, 4]:
    print(bits, params * bits / 8 / 1e9)
